INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`) VALUES
(1839, 'zhCN', '唉……那就这样吧，就这样吧。回去吧，继续去干你那送死的活儿。', '唉……那就这样吧，就这样吧。回去吧，继续去干你那送死的活儿。'),
(4636, 'zhCN', '我不会……永远不会忘记你做过的事……$B$B求求你，让我一个人待着吧……', '我不会……永远不会忘记你做过的事……$B$B求求你，让我一个人待着吧……'),
(8473, 'zhCN', '谢谢你把那块矿石取来并交给魔导师卡雷斯特斯，$c。我想我该回去了，可我害怕——没能自己拿到矿石，等着我的会是什么样的惩罚。$B$B别告诉魔导师，好吗？', '谢谢你把那块矿石取来并交给魔导师卡雷斯特斯，$c。我想我该回去了，可我害怕——没能自己拿到矿石，等着我的会是什么样的惩罚。$B$B别告诉魔导师，好吗？'),
(9293, 'zhCN', '嘿！我之前是不是给过你一捆皮子？$B$B不管怎样，能从那个恶棍甘克利·烂拳的无情魔爪里被救出来，我很高兴！', '嘿！我之前是不是给过你一捆皮子？$B$B不管怎样，能从那个恶棍甘克利·烂拳的无情魔爪里被救出来，我很高兴！'),
(9409, 'zhCN', '你若继续帮我们对抗燃烧军团，我们仍然感激不尽。萨尔的营地在这一带的西边，他需要你的帮助。', '你若继续帮我们对抗燃烧军团，我们仍然感激不尽。萨尔的营地在这一带的西边，他需要你的帮助。'),
(9415, 'zhCN', '恭喜！今天又赢得了一场伟大的胜利。', '恭喜！今天又赢得了一场伟大的胜利。'),
(11074, 'zhCN', '忘记"药剂专精"的技能可不是能轻描淡写的事。$B$B你当真确定吗？', '忘记"药剂专精"的技能可不是能轻描淡写的事。$B$B你当真确定吗？'),
(13944, 'zhCN', '你必须击败桑德瓦尔王子。那是你唯一的生路，$c。', '你必须击败桑德瓦尔王子。那是你唯一的生路，$c。'),
(9975000, 'zhCN', '<亨利开口时，声音像是舌头永远粘在了嘴底下。>$B$B你晓得额，俺当工程师也没多长时间，有时候俺连自己会啥都觉得惊讶。', '<亨利开口时，声音像是舌头永远粘在了嘴底下。>$B$B你晓得额，俺当工程师也没多长时间，有时候俺连自己会啥都觉得惊讶。'),
(9975001, 'zhCN', '有水果、牛奶，任何能在塔纳利斯这大热天里让你凉快下来的东西。', '有水果、牛奶，任何能在塔纳利斯这大热天里让你凉快下来的东西。'),
(9975002, 'zhCN', '两个星期前，我把这副臭皮囊从酒吧凳上拽起来，说要重新做人。我来这儿是找瑟银的。找到了，可事情还不止这些。$B$B往南不远有一处遗迹。里头有龙，青铜的多得像沙子。其中一条守着一件宝贝——一把看着极其古老的剑。等我这两条腿不再发抖，我就回去把它取来。', '两个星期前，我把这副臭皮囊从酒吧凳上拽起来，说要重新做人。我来这儿是找瑟银的。找到了，可事情还不止这些。$B$B往南不远有一处遗迹。里头有龙，青铜的多得像沙子。其中一条守着一件宝贝——一把看着极其古老的剑。等我这两条腿不再发抖，我就回去把它取来。'),
(9975003, 'zhCN', '啊，我想我们还没正式认识。我叫泽贝尔·什普利特，是威名远扬的加基森搬运工。', '啊，我想我们还没正式认识。我叫泽贝尔·什普利特，是威名远扬的加基森搬运工。'),
(9975004, 'zhCN', '沙漠会说矮人语，但只对肯倾听的人说。这座小镇寒酸得可怜，真正要紧的是外面的沙丘。', '沙漠会说矮人语，但只对肯倾听的人说。这座小镇寒酸得可怜，真正要紧的是外面的沙丘。'),
(9975005, 'zhCN', '地精工程的秘诀？一份科学，两份胆量，再加三份——东西开始怪叫时撒腿就跑的脚程。', '地精工程的秘诀？一份科学，两份胆量，再加三份——东西开始怪叫时撒腿就跑的脚程。'),
(9975006, 'zhCN', '<伦萨呆呆地望着不远处。他的一句话像是从某个已经想了很久的念头中间开始的>$B$B……你知道，造火箭其实只有两条路。要么造一套系统，去造那些能从零开始造火箭的工程师；要么直接借用某个高度发达的宇航文明的技术——几年前他们把自己那枚更先进的火箭撞到了我们这颗星球上。$B$B<伦萨转过头，看着一名工程师不知疲倦地敲打那艘摇摇欲坠、只造了一半的火箭。>$B$B……我还是不太明白自己当初为什么选了第一条路。', '<伦萨呆呆地望着不远处。他的一句话像是从某个已经想了很久的念头中间开始的>$B$B……你知道，造火箭其实只有两条路。要么造一套系统，去造那些能从零开始造火箭的工程师；要么直接借用某个高度发达的宇航文明的技术——几年前他们把自己那枚更先进的火箭撞到了我们这颗星球上。$B$B<伦萨转过头，看着一名工程师不知疲倦地敲打那艘摇摇欲坠、只造了一半的火箭。>$B$B……我还是不太明白自己当初为什么选了第一条路。'),
(9975007, 'zhCN', '那么，$r，要点什么？', '那么，$r，要点什么？'),
(9975008, 'zhCN', '是啊，最近五批货他一分钱都没给我。所以你可以替他带句话：要么把每一批都结清，连利息一起；要么他这辈子都别想再见到一件专利的烟筒货。', '是啊，最近五批货他一分钱都没给我。所以你可以替他带句话：要么把每一批都结清，连利息一起；要么他这辈子都别想再见到一件专利的烟筒货。');
